-- Phase 5B: transactional staffing and supplier workflows.
-- This migration deliberately replaces the bounded Phase 5A action stubs without
-- rewriting deployed history. All money below is an encumbrance, never a payment.
CREATE TABLE public.festival_operations_communications (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.festival_operations_requests(id) ON DELETE RESTRICT,
 recipient_profile_id uuid REFERENCES public.profiles(id), recipient_company_id uuid REFERENCES public.companies(id),
 channel text NOT NULL CHECK(channel IN ('mail','notification')), event_type text NOT NULL, title text NOT NULL, body text NOT NULL,
 action_path text NOT NULL DEFAULT '/jobs', created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(num_nonnulls(recipient_profile_id,recipient_company_id)=1), UNIQUE(request_id,channel,event_type,recipient_profile_id,recipient_company_id)
);
ALTER TABLE public.festival_operations_communications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.festival_operations_communications FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public._festival_operations_authorised(p_company uuid,p_actor uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT auth.uid() IS NOT NULL AND p_actor IS NOT NULL AND public._festival_artist_manager(p_company,p_actor) $$;
CREATE OR REPLACE FUNCTION public._festival_supplier_authorised(p_company uuid,p_actor uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.companies c LEFT JOIN public.company_employees e ON e.company_id=c.id AND e.profile_id=p_actor AND e.status='active' WHERE c.id=p_company AND c.status='active' AND (c.owner_id=auth.uid() OR lower(coalesce(e.role,'')) IN ('ceo','manager'))) $$;
CREATE OR REPLACE FUNCTION public._festival_operations_begin_action(p_company uuid,p_action text,p_target uuid,p_key uuid,p_payload jsonb) RETURNS public.festival_operations_requests
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();r public.festival_operations_requests%ROWTYPE;h text:=encode(digest(p_payload::text,'sha256'),'hex'); BEGIN
 IF auth.uid() IS NULL OR a IS NULL OR p_key IS NULL THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(a::text||p_action||p_key::text,0));
 SELECT * INTO r FROM public.festival_operations_requests WHERE actor_profile_id=a AND action=p_action AND target_id IS NOT DISTINCT FROM p_target AND idempotency_key=p_key;
 IF FOUND THEN IF r.payload_hash<>h THEN RAISE EXCEPTION 'festival_operations_idempotency_conflict' USING ERRCODE='P0001'; END IF; RETURN r; END IF;
 INSERT INTO public.festival_operations_requests(festival_company_id,actor_profile_id,action,target_id,idempotency_key,payload_hash) VALUES(p_company,a,p_action,p_target,p_key,h) RETURNING * INTO r; RETURN r; END $$;
CREATE OR REPLACE FUNCTION public._festival_operations_finish_action(p_request uuid,p_company uuid,p_entity jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE z jsonb; BEGIN z:=jsonb_build_object('operations',public._festival_operations_result(p_company),'entity',p_entity,'communications',coalesce((SELECT jsonb_agg(to_jsonb(c)) FROM public.festival_operations_communications c WHERE c.request_id=p_request),'[]'::jsonb)); UPDATE public.festival_operations_requests SET status='succeeded',result=z,completed_at=now() WHERE id=p_request; RETURN z; END $$;
CREATE OR REPLACE FUNCTION public._festival_operations_audit(p_request uuid,p_company uuid,p_type text,p_id uuid,p_event text,p_old text,p_new text,p_version int) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ INSERT INTO public.festival_operations_audit(festival_company_id,actor_profile_id,entity_type,entity_id,event_type,previous_state,new_state,version,request_id) VALUES(p_company,public._caller_profile_id(),p_type,p_id,p_event,p_old,p_new,p_version,p_request) ON CONFLICT(request_id) DO NOTHING $$;
CREATE OR REPLACE FUNCTION public._festival_operations_notify(p_request uuid,p_profile uuid,p_company uuid,p_event text,p_title text,p_body text,p_path text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ INSERT INTO public.festival_operations_communications(request_id,recipient_profile_id,recipient_company_id,channel,event_type,title,body,action_path) SELECT p_request,p_profile,p_company,c,p_event,p_title,p_body,p_path FROM unnest(ARRAY['mail','notification']) c ON CONFLICT DO NOTHING $$;
CREATE OR REPLACE FUNCTION public._festival_operations_create_commitment(p_company uuid,p_assignment uuid,p_contract uuid,p_amount bigint,p_currency text) RETURNS public.festival_financial_commitments LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE x public.festival_financial_commitments%ROWTYPE; BEGIN IF p_amount<0 OR num_nonnulls(p_assignment,p_contract)<>1 THEN RAISE EXCEPTION 'festival_operations_action_invalid' USING ERRCODE='P0001'; END IF; INSERT INTO public.festival_financial_commitments(festival_company_id,staff_assignment_id,supplier_contract_id,category,amount_minor,currency_code,status) VALUES(p_company,p_assignment,p_contract,CASE WHEN p_assignment IS NULL THEN 'supplier_contract' ELSE 'staff_assignment' END,p_amount,p_currency,'committed') ON CONFLICT(staff_assignment_id) DO UPDATE SET staff_assignment_id=excluded.staff_assignment_id RETURNING * INTO x; IF x.id IS NULL THEN SELECT * INTO x FROM public.festival_financial_commitments WHERE supplier_contract_id=p_contract; END IF; RETURN x; END $$;
CREATE OR REPLACE FUNCTION public._festival_operations_cancel_commitment(p_assignment uuid,p_contract uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ UPDATE public.festival_financial_commitments SET status='released',released_at=now() WHERE status='committed' AND (staff_assignment_id=p_assignment OR supplier_contract_id=p_contract) $$;

CREATE OR REPLACE FUNCTION public.publish_festival_staff_vacancy(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();r public.festival_staffing_requirements%ROWTYPE;op public.festival_operations_plans%ROWTYPE;v public.festival_staff_vacancies%ROWTYPE;q public.festival_operations_requests%ROWTYPE;c uuid:=(p_payload->>'festivalCompanyId')::uuid; BEGIN SELECT sr.* INTO r FROM public.festival_staffing_requirements sr JOIN public.festival_operations_plans x ON x.id=sr.festival_operations_plan_id WHERE sr.id=(p_payload->>'staffingRequirementId')::uuid AND x.festival_company_id=c FOR UPDATE; SELECT * INTO op FROM public.festival_operations_plans WHERE id=r.festival_operations_plan_id; IF NOT public._festival_operations_authorised(c,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(c,'publish_staff_vacancy',r.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; IF (p_payload->>'expectedVersion')::int<>op.planning_version OR (p_payload->>'positionsAvailable')::int<=0 OR (p_payload->>'positionsAvailable')::int>r.required_count-(SELECT count(*) FROM public.festival_staff_assignments WHERE staffing_requirement_id=r.id AND status IN ('committed','active')) OR (p_payload->>'payMinor')::bigint<0 OR (p_payload->>'startsAt')::timestamptz>=(p_payload->>'endsAt')::timestamptz OR (p_payload->>'applicationDeadline')::timestamptz>=(p_payload->>'startsAt')::timestamptz OR ((p_payload->>'payType')='unpaid_volunteer' AND r.safety_critical) OR ((p_payload->>'playerOnly')::boolean AND NOT r.player_eligible) OR ((p_payload->>'npcFallbackAllowed')::boolean AND NOT r.npc_eligible) THEN RAISE EXCEPTION 'festival_staff_vacancy_invalid' USING ERRCODE='P0001'; END IF; INSERT INTO public.festival_staff_vacancies(festival_operations_plan_id,staffing_requirement_id,title,description,employment_type,positions_available,pay_type,pay_minor,currency_code,starts_at,ends_at,application_deadline,minimum_skill_level,minimum_experience,player_only,npc_fallback_allowed,status) VALUES(op.id,r.id,p_payload->>'title',p_payload->>'description',p_payload->>'employmentType',(p_payload->>'positionsAvailable')::int,p_payload->>'payType',(p_payload->>'payMinor')::bigint,op.currency_code,(p_payload->>'startsAt')::timestamptz,(p_payload->>'endsAt')::timestamptz,(p_payload->>'applicationDeadline')::timestamptz,r.minimum_skill_level,r.minimum_experience,coalesce((p_payload->>'playerOnly')::boolean,false),coalesce((p_payload->>'npcFallbackAllowed')::boolean,true),'published') RETURNING * INTO v; UPDATE public.festival_staffing_requirements SET status='recruiting',updated_at=now() WHERE id=r.id; PERFORM public._festival_operations_audit(q.id,c,'vacancy',v.id,'vacancy_published',NULL,'published',1); RETURN public._festival_operations_finish_action(q.id,c,to_jsonb(v)); END $$;

CREATE OR REPLACE FUNCTION public.apply_for_festival_staff_vacancy(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();v public.festival_staff_vacancies%ROWTYPE;r public.festival_staffing_requirements%ROWTYPE;op public.festival_operations_plans%ROWTYPE;x public.festival_staff_applications%ROWTYPE;q public.festival_operations_requests%ROWTYPE; BEGIN SELECT * INTO v FROM public.festival_staff_vacancies WHERE id=(p_payload->>'vacancyId')::uuid FOR UPDATE; SELECT * INTO r FROM public.festival_staffing_requirements WHERE id=v.staffing_requirement_id; SELECT * INTO op FROM public.festival_operations_plans WHERE id=v.festival_operations_plan_id; q:=public._festival_operations_begin_action(op.festival_company_id,'apply_staff_vacancy',v.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; IF v.status<>'published' OR v.application_deadline<=now() OR v.positions_filled>=v.positions_available OR NOT r.player_eligible OR coalesce((p_payload->>'expectedPayMinor')::bigint,0)<0 OR EXISTS(SELECT 1 FROM public.festival_staff_assignments WHERE profile_id=a AND status IN ('committed','active') AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(v.starts_at,v.ends_at,'[)')) THEN RAISE EXCEPTION 'festival_staff_applicant_ineligible' USING ERRCODE='P0001'; END IF; BEGIN INSERT INTO public.festival_staff_applications(vacancy_id,applicant_profile_id,skill_snapshot,experience_snapshot,availability_snapshot,message,expected_pay_minor) VALUES(v.id,a,jsonb_build_object('minimumRequired',r.minimum_skill_level,'eligible',NOT r.safety_critical OR coalesce((p_payload->>'qualified')::boolean,false)),coalesce((p_payload->>'experience')::int,0),jsonb_build_object('state','available','capturedAt',now()),nullif(btrim(p_payload->>'message'),''),coalesce((p_payload->>'expectedPayMinor')::bigint,v.pay_minor)) RETURNING * INTO x; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'festival_staff_application_duplicate' USING ERRCODE='P0001'; END; IF r.safety_critical AND NOT coalesce((x.skill_snapshot->>'eligible')::boolean,false) THEN RAISE EXCEPTION 'festival_staff_applicant_unqualified' USING ERRCODE='P0001'; END IF; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'application',x.id,'application_submitted',NULL,'submitted',1); PERFORM public._festival_operations_notify(q.id,a,NULL,'application_submitted','Festival job application submitted','Your application was delivered to Festival management.','/jobs'); RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(x)); END $$;

CREATE OR REPLACE FUNCTION public.withdraw_festival_staff_application(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_staff_applications%ROWTYPE;c uuid;q public.festival_operations_requests%ROWTYPE;old text; BEGIN SELECT * INTO x FROM public.festival_staff_applications WHERE id=(p_payload->>'applicationId')::uuid FOR UPDATE; SELECT op.festival_company_id INTO c FROM public.festival_staff_vacancies v JOIN public.festival_operations_plans op ON op.id=v.festival_operations_plan_id WHERE v.id=x.vacancy_id; q:=public._festival_operations_begin_action(c,'withdraw_staff_application',x.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; IF x.applicant_profile_id<>a OR x.application_version<>(p_payload->>'expectedVersion')::int OR x.status NOT IN ('submitted','under_review','shortlisted') OR EXISTS(SELECT 1 FROM public.festival_staff_assignments WHERE application_id=x.id) THEN RAISE EXCEPTION 'festival_staff_application_invalid_transition' USING ERRCODE='P0001'; END IF; old:=x.status; UPDATE public.festival_staff_applications SET status='withdrawn',withdrawn_at=now(),application_version=application_version+1 WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_operations_audit(q.id,c,'application',x.id,'application_withdrawn',old,'withdrawn',x.application_version); RETURN public._festival_operations_finish_action(q.id,c,to_jsonb(x)); END $$;

CREATE OR REPLACE FUNCTION public.review_festival_staff_application(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_staff_applications%ROWTYPE;c uuid;q public.festival_operations_requests%ROWTYPE;ns text;old text; BEGIN SELECT * INTO x FROM public.festival_staff_applications WHERE id=(p_payload->>'applicationId')::uuid FOR UPDATE; SELECT op.festival_company_id INTO c FROM public.festival_staff_vacancies v JOIN public.festival_operations_plans op ON op.id=v.festival_operations_plan_id WHERE v.id=x.vacancy_id; IF NOT public._festival_operations_authorised(c,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(c,'review_staff_application',x.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; ns:=CASE p_payload->>'action' WHEN 'mark_under_review' THEN 'under_review' WHEN 'shortlist' THEN 'shortlisted' WHEN 'reject' THEN 'rejected' END; IF x.application_version<>(p_payload->>'expectedVersion')::int OR ns IS NULL OR (x.status,ns) NOT IN (('submitted','under_review'),('submitted','shortlisted'),('under_review','shortlisted'),('submitted','rejected'),('under_review','rejected'),('shortlisted','rejected')) THEN RAISE EXCEPTION 'festival_staff_application_invalid_transition' USING ERRCODE='P0001'; END IF; old:=x.status; UPDATE public.festival_staff_applications SET status=ns,reviewed_at=now(),application_version=application_version+1 WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_operations_audit(q.id,c,'application',x.id,'application_'||ns,old,ns,x.application_version); PERFORM public._festival_operations_notify(q.id,x.applicant_profile_id,NULL,'application_'||ns,'Festival job application update','Your Festival job application is now '||replace(ns,'_',' ')||'.','/jobs'); RETURN public._festival_operations_finish_action(q.id,c,to_jsonb(x)); END $$;
CREATE OR REPLACE FUNCTION public.hire_festival_staff_applicant(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_staff_applications%ROWTYPE;v public.festival_staff_vacancies%ROWTYPE;r public.festival_staffing_requirements%ROWTYPE;op public.festival_operations_plans%ROWTYPE;s public.festival_staff_assignments%ROWTYPE;q public.festival_operations_requests%ROWTYPE;spent bigint;pay bigint:=(p_payload->>'agreedPayMinor')::bigint; BEGIN SELECT * INTO x FROM public.festival_staff_applications WHERE id=(p_payload->>'applicationId')::uuid FOR UPDATE; SELECT * INTO v FROM public.festival_staff_vacancies WHERE id=x.vacancy_id FOR UPDATE; SELECT * INTO r FROM public.festival_staffing_requirements WHERE id=v.staffing_requirement_id FOR UPDATE; SELECT * INTO op FROM public.festival_operations_plans WHERE id=v.festival_operations_plan_id FOR UPDATE; IF NOT public._festival_operations_authorised(op.festival_company_id,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'hire_staff_applicant',x.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; SELECT coalesce(sum(amount_minor),0) INTO spent FROM public.festival_financial_commitments WHERE festival_company_id=op.festival_company_id AND staff_assignment_id IS NOT NULL AND status='committed'; IF x.application_version<>(p_payload->>'expectedApplicationVersion')::int THEN RAISE EXCEPTION 'festival_staff_application_stale' USING ERRCODE='P0001'; END IF; IF x.status NOT IN ('submitted','under_review','shortlisted') OR v.status<>'published' OR v.positions_filled>=v.positions_available OR pay<0 OR spent+pay>op.staff_budget_minor+op.contingency_budget_minor OR (r.safety_critical AND NOT coalesce((x.skill_snapshot->>'eligible')::boolean,false)) OR EXISTS(SELECT 1 FROM public.festival_staff_assignments z WHERE z.profile_id=x.applicant_profile_id AND z.status IN ('committed','active') AND tstzrange(z.starts_at,z.ends_at,'[)')&&tstzrange((p_payload->>'assignmentStartsAt')::timestamptz,(p_payload->>'assignmentEndsAt')::timestamptz,'[)')) THEN RAISE EXCEPTION 'festival_staff_budget_or_eligibility_invalid' USING ERRCODE='P0001'; END IF; INSERT INTO public.festival_staff_assignments(festival_operations_plan_id,staffing_requirement_id,vacancy_id,application_id,assignment_source,profile_id,role_type,agreed_pay_minor,currency_code,quality_score,starts_at,ends_at) VALUES(op.id,r.id,v.id,x.id,'player_application',x.applicant_profile_id,r.role_type,pay,op.currency_code,greatest(r.minimum_skill_level,least(100,coalesce(x.experience_snapshot,0))),(p_payload->>'assignmentStartsAt')::timestamptz,(p_payload->>'assignmentEndsAt')::timestamptz) RETURNING * INTO s; PERFORM public._festival_operations_create_commitment(op.festival_company_id,s.id,NULL,pay,op.currency_code); UPDATE public.festival_staff_applications SET status='accepted',reviewed_at=now(),application_version=application_version+1 WHERE id=x.id; UPDATE public.festival_staff_vacancies SET positions_filled=positions_filled+1,status=CASE WHEN positions_filled+1>=positions_available THEN 'filled' ELSE status END,updated_at=now() WHERE id=v.id; UPDATE public.festival_staffing_requirements SET status=CASE WHEN (SELECT count(*) FROM public.festival_staff_assignments WHERE staffing_requirement_id=r.id AND status='committed')>=required_count THEN 'covered' ELSE 'recruiting' END WHERE id=r.id; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'assignment',s.id,'assignment_created',NULL,'committed',1); PERFORM public._festival_operations_notify(q.id,x.applicant_profile_id,NULL,'assignment_created','Festival job accepted','This creates a contractual commitment. Payment occurs during a later Festival settlement phase.','/jobs'); RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(s)); END $$;

CREATE OR REPLACE FUNCTION public.hire_festival_npc_staff(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();r public.festival_staffing_requirements%ROWTYPE;op public.festival_operations_plans%ROWTYPE;s public.festival_staff_assignments%ROWTYPE;q public.festival_operations_requests%ROWTYPE;i int;cnt int:=(p_payload->>'count')::int;cost bigint;arr jsonb:='[]'; BEGIN SELECT * INTO r FROM public.festival_staffing_requirements WHERE id=(p_payload->>'staffingRequirementId')::uuid FOR UPDATE; SELECT * INTO op FROM public.festival_operations_plans WHERE id=r.festival_operations_plan_id FOR UPDATE; IF NOT public._festival_operations_authorised(op.festival_company_id,a) OR NOT r.npc_eligible THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'hire_npc_staff',r.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; IF op.planning_version<>(p_payload->>'expectedPlanVersion')::int THEN RAISE EXCEPTION 'festival_operations_plan_stale' USING ERRCODE='P0001'; END IF; IF cnt NOT BETWEEN 1 AND 10 OR cnt>(r.required_count-(SELECT count(*) FROM public.festival_staff_assignments WHERE staffing_requirement_id=r.id AND status='committed')) OR (p_payload->>'quality')::int<r.minimum_skill_level THEN RAISE EXCEPTION 'festival_npc_staff_unavailable' USING ERRCODE='P0001'; END IF; cost:=greatest(1000,r.estimated_cost_minor/r.required_count)*(100+least(100,20+cnt*5))/100; FOR i IN 1..cnt LOOP INSERT INTO public.festival_staff_assignments(festival_operations_plan_id,staffing_requirement_id,assignment_source,npc_staff_id,role_type,agreed_pay_minor,currency_code,quality_score,starts_at,ends_at) VALUES(op.id,r.id,'npc_hire',(p_payload->>'npcStaffId')::uuid,r.role_type,cost,op.currency_code,(p_payload->>'quality')::int,r.coverage_start,r.coverage_end) RETURNING * INTO s; PERFORM public._festival_operations_create_commitment(op.festival_company_id,s.id,NULL,cost,op.currency_code); arr:=arr||to_jsonb(s); END LOOP; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'staffing_requirement',r.id,'npc_staff_hired',r.status,'recruiting',op.planning_version); RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,jsonb_build_object('assignments',arr)); END $$;

CREATE OR REPLACE FUNCTION public.assign_festival_staff_shift(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();s public.festival_staff_assignments%ROWTYPE;op public.festival_operations_plans%ROWTYPE;x public.festival_staff_shifts%ROWTYPE;q public.festival_operations_requests%ROWTYPE;st timestamptz:=(p_payload->>'startsAt')::timestamptz;en timestamptz:=(p_payload->>'endsAt')::timestamptz; BEGIN SELECT * INTO s FROM public.festival_staff_assignments WHERE id=(p_payload->>'assignmentId')::uuid FOR UPDATE; SELECT * INTO op FROM public.festival_operations_plans WHERE id=s.festival_operations_plan_id; IF NOT public._festival_operations_authorised(op.festival_company_id,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'assign_staff_shift',s.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; IF s.assignment_version<>(p_payload->>'expectedAssignmentVersion')::int OR s.status NOT IN ('committed','active') OR st<s.starts_at OR en>s.ends_at OR en<=st OR en-st>interval '16 hours' OR (p_payload->>'breakMinutes')::int NOT BETWEEN 0 AND 240 OR NOT EXISTS(SELECT 1 FROM public.festival_operational_departments WHERE id=(p_payload->>'departmentId')::uuid AND festival_operations_plan_id=op.id) OR EXISTS(SELECT 1 FROM public.festival_staff_shifts WHERE staff_assignment_id=s.id AND status<>'cancelled' AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(st,en,'[)')) THEN RAISE EXCEPTION 'festival_staff_shift_conflict' USING ERRCODE='P0001'; END IF; INSERT INTO public.festival_staff_shifts(festival_operations_plan_id,staff_assignment_id,department_id,festival_date,starts_at,ends_at,break_minutes,location_type,stage_id,coverage_type) VALUES(op.id,s.id,(p_payload->>'departmentId')::uuid,(p_payload->>'festivalDate')::date,st,en,(p_payload->>'breakMinutes')::int,p_payload->>'locationType',(p_payload->>'stageId')::uuid,p_payload->>'coverageType') RETURNING * INTO x; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'shift',x.id,'shift_assigned',NULL,'planned',1); IF s.profile_id IS NOT NULL THEN PERFORM public._festival_operations_notify(q.id,s.profile_id,NULL,'shift_assigned','Festival shift assigned','A shift has been added to your Festival assignment.','/jobs'); END IF; RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(x)); END $$;

CREATE OR REPLACE FUNCTION public.cancel_festival_staff_assignment(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();s public.festival_staff_assignments%ROWTYPE;op public.festival_operations_plans%ROWTYPE;q public.festival_operations_requests%ROWTYPE; BEGIN SELECT * INTO s FROM public.festival_staff_assignments WHERE id=(p_payload->>'assignmentId')::uuid FOR UPDATE; SELECT * INTO op FROM public.festival_operations_plans WHERE id=s.festival_operations_plan_id; IF NOT public._festival_operations_authorised(op.festival_company_id,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'cancel_staff_assignment',s.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; IF s.assignment_version<>(p_payload->>'expectedAssignmentVersion')::int OR s.status NOT IN ('planned','committed') OR s.starts_at<=now() THEN RAISE EXCEPTION 'festival_staff_assignment_invalid_transition' USING ERRCODE='P0001'; END IF; UPDATE public.festival_staff_assignments SET status='cancelled',cancelled_at=now(),updated_at=now(),assignment_version=assignment_version+1 WHERE id=s.id RETURNING * INTO s; UPDATE public.festival_staff_shifts SET status='cancelled',updated_at=now() WHERE staff_assignment_id=s.id AND starts_at>now(); PERFORM public._festival_operations_cancel_commitment(s.id,NULL); IF s.vacancy_id IS NOT NULL THEN UPDATE public.festival_staff_vacancies SET positions_filled=greatest(0,positions_filled-1),status='published' WHERE id=s.vacancy_id; END IF; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'assignment',s.id,'assignment_cancelled','committed','cancelled',s.assignment_version); RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(s)); END $$;
CREATE OR REPLACE FUNCTION public.publish_festival_supplier_requirement(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();r public.festival_supplier_requirements%ROWTYPE;op public.festival_operations_plans%ROWTYPE;q public.festival_operations_requests%ROWTYPE; BEGIN SELECT * INTO r FROM public.festival_supplier_requirements WHERE id=(p_payload->>'supplierRequirementId')::uuid FOR UPDATE; SELECT * INTO op FROM public.festival_operations_plans WHERE id=r.festival_operations_plan_id; IF NOT public._festival_operations_authorised(op.festival_company_id,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'publish_supplier_requirement',r.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; IF op.planning_version<>(p_payload->>'expectedVersion')::int OR r.status NOT IN ('open','draft') OR coalesce((p_payload->>'quoteDeadline')::timestamptz,r.delivery_start)>=r.delivery_start THEN RAISE EXCEPTION 'festival_supplier_requirement_invalid' USING ERRCODE='P0001'; END IF; UPDATE public.festival_supplier_requirements SET status='published',updated_at=now() WHERE id=r.id RETURNING * INTO r; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'supplier_requirement',r.id,'requirement_published','open','published',1); RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(r)); END $$;

CREATE OR REPLACE FUNCTION public.submit_festival_supplier_quote(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();r public.festival_supplier_requirements%ROWTYPE;op public.festival_operations_plans%ROWTYPE;x public.festival_supplier_quotes%ROWTYPE;q public.festival_operations_requests%ROWTYPE;co uuid:=(p_payload->>'supplierCompanyId')::uuid;total bigint; BEGIN SELECT * INTO r FROM public.festival_supplier_requirements WHERE id=(p_payload->>'supplierRequirementId')::uuid FOR UPDATE; SELECT * INTO op FROM public.festival_operations_plans WHERE id=r.festival_operations_plan_id; IF NOT public._festival_supplier_authorised(co,a) OR NOT r.player_company_eligible THEN RAISE EXCEPTION 'festival_supplier_quote_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'submit_supplier_quote',r.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; total:=(p_payload->>'baseCostMinor')::bigint+(p_payload->>'deliveryCostMinor')::bigint+(p_payload->>'setupCostMinor')::bigint+(p_payload->>'staffingCostMinor')::bigint; IF r.status<>'published' OR least((p_payload->>'baseCostMinor')::bigint,(p_payload->>'deliveryCostMinor')::bigint,(p_payload->>'setupCostMinor')::bigint,(p_payload->>'staffingCostMinor')::bigint)<0 OR (p_payload->>'depositMinor')::bigint>total OR (p_payload->>'capacityOffered')::int<=0 OR (p_payload->>'expiresAt')::timestamptz<=now() OR EXISTS(SELECT 1 FROM public.festival_supplier_quotes WHERE supplier_requirement_id=r.id AND supplier_company_id=co AND status IN ('submitted','under_review')) THEN RAISE EXCEPTION 'festival_supplier_quote_invalid' USING ERRCODE='P0001'; END IF; INSERT INTO public.festival_supplier_quotes(supplier_requirement_id,supplier_source,supplier_company_id,submitted_by_profile_id,currency_code,base_cost_minor,delivery_cost_minor,setup_cost_minor,staffing_cost_minor,deposit_minor,total_cost_minor,quality_score,reliability_score,capacity_offered,delivery_terms,service_terms,expires_at) VALUES(r.id,'player_company',co,a,op.currency_code,(p_payload->>'baseCostMinor')::bigint,(p_payload->>'deliveryCostMinor')::bigint,(p_payload->>'setupCostMinor')::bigint,(p_payload->>'staffingCostMinor')::bigint,(p_payload->>'depositMinor')::bigint,total,greatest(r.minimum_quality,50),greatest(25,least(100,(SELECT coalesce(reputation_score,50) FROM public.companies WHERE id=co))),least(r.quantity,(p_payload->>'capacityOffered')::int),coalesce(p_payload->'deliveryTerms','{}'),coalesce(p_payload->'serviceTerms','{}'),(p_payload->>'expiresAt')::timestamptz) RETURNING * INTO x; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'supplier_quote',x.id,'quote_submitted',NULL,'submitted',1); PERFORM public._festival_operations_notify(q.id,NULL,co,'quote_submitted','Festival supplier quote submitted','Your quote was delivered to Festival management.','/companies'); RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(x)); END $$;

CREATE OR REPLACE FUNCTION public.withdraw_festival_supplier_quote(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_supplier_quotes%ROWTYPE;op public.festival_operations_plans%ROWTYPE;q public.festival_operations_requests%ROWTYPE; BEGIN SELECT * INTO x FROM public.festival_supplier_quotes WHERE id=(p_payload->>'quoteId')::uuid FOR UPDATE; SELECT o.* INTO op FROM public.festival_supplier_requirements r JOIN public.festival_operations_plans o ON o.id=r.festival_operations_plan_id WHERE r.id=x.supplier_requirement_id; IF NOT public._festival_supplier_authorised(x.supplier_company_id,a) THEN RAISE EXCEPTION 'festival_supplier_quote_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'withdraw_supplier_quote',x.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; IF x.quote_version<>(p_payload->>'expectedVersion')::int OR x.status NOT IN ('submitted','under_review') OR EXISTS(SELECT 1 FROM public.festival_supplier_contracts WHERE accepted_quote_id=x.id) THEN RAISE EXCEPTION 'festival_supplier_quote_invalid_transition' USING ERRCODE='P0001'; END IF; UPDATE public.festival_supplier_quotes SET status='withdrawn',quote_version=quote_version+1,updated_at=now() WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'supplier_quote',x.id,'quote_withdrawn','submitted','withdrawn',x.quote_version); RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(x)); END $$;

CREATE OR REPLACE FUNCTION public.review_festival_supplier_quote(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_supplier_quotes%ROWTYPE;op public.festival_operations_plans%ROWTYPE;q public.festival_operations_requests%ROWTYPE;ns text; BEGIN SELECT * INTO x FROM public.festival_supplier_quotes WHERE id=(p_payload->>'quoteId')::uuid FOR UPDATE; SELECT o.* INTO op FROM public.festival_supplier_requirements r JOIN public.festival_operations_plans o ON o.id=r.festival_operations_plan_id WHERE r.id=x.supplier_requirement_id; IF NOT public._festival_operations_authorised(op.festival_company_id,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'review_supplier_quote',x.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; ns:=CASE p_payload->>'action' WHEN 'mark_under_review' THEN 'under_review' WHEN 'decline' THEN 'declined' END; IF x.quote_version<>(p_payload->>'expectedVersion')::int OR x.expires_at<=now() OR ns IS NULL OR (x.status,ns) NOT IN (('submitted','under_review'),('submitted','declined'),('under_review','declined')) THEN RAISE EXCEPTION 'festival_supplier_quote_invalid_transition' USING ERRCODE='P0001'; END IF; UPDATE public.festival_supplier_quotes SET status=ns,quote_version=quote_version+1,updated_at=now() WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'supplier_quote',x.id,'quote_'||ns,NULL,ns,x.quote_version); IF x.supplier_company_id IS NOT NULL THEN PERFORM public._festival_operations_notify(q.id,NULL,x.supplier_company_id,'quote_'||ns,'Festival supplier quote update','Your quote is now '||replace(ns,'_',' ')||'.','/companies'); END IF; RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(x)); END $$;
CREATE OR REPLACE FUNCTION public.accept_festival_supplier_quote(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_supplier_quotes%ROWTYPE;r public.festival_supplier_requirements%ROWTYPE;op public.festival_operations_plans%ROWTYPE;c public.festival_supplier_contracts%ROWTYPE;q public.festival_operations_requests%ROWTYPE;spent bigint; BEGIN SELECT * INTO x FROM public.festival_supplier_quotes WHERE id=(p_payload->>'quoteId')::uuid FOR UPDATE; SELECT * INTO r FROM public.festival_supplier_requirements WHERE id=x.supplier_requirement_id FOR UPDATE; SELECT * INTO op FROM public.festival_operations_plans WHERE id=r.festival_operations_plan_id FOR UPDATE; IF NOT public._festival_operations_authorised(op.festival_company_id,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'accept_supplier_quote',x.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; SELECT coalesce(sum(amount_minor),0) INTO spent FROM public.festival_financial_commitments WHERE festival_company_id=op.festival_company_id AND supplier_contract_id IS NOT NULL AND status='committed'; IF x.quote_version<>(p_payload->>'expectedQuoteVersion')::int THEN RAISE EXCEPTION 'festival_supplier_quote_stale' USING ERRCODE='P0001'; END IF; IF x.status NOT IN ('submitted','under_review') OR x.expires_at<=now() OR x.currency_code<>op.currency_code OR spent+x.total_cost_minor>op.supplier_budget_minor+op.contingency_budget_minor OR x.quality_score<r.minimum_quality OR EXISTS(SELECT 1 FROM public.festival_supplier_contracts WHERE supplier_requirement_id=r.id AND status IN ('committed','awaiting_delivery','active')) THEN RAISE EXCEPTION 'festival_supplier_budget_or_eligibility_invalid' USING ERRCODE='P0001'; END IF; INSERT INTO public.festival_supplier_contracts(festival_operations_plan_id,supplier_requirement_id,accepted_quote_id,supplier_source,supplier_company_id,npc_supplier_id,currency_code,total_commitment_minor,deposit_commitment_minor,quality_score,reliability_score,delivery_start,delivery_end,service_start,service_end,terms_snapshot) VALUES(op.id,r.id,x.id,x.supplier_source,x.supplier_company_id,x.npc_supplier_id,op.currency_code,x.total_cost_minor,x.deposit_minor,x.quality_score,x.reliability_score,r.delivery_start,r.delivery_end,r.service_start,r.service_end,jsonb_build_object('delivery',x.delivery_terms,'service',x.service_terms,'depositMinor',x.deposit_minor,'balanceMinor',x.total_cost_minor-x.deposit_minor)) RETURNING * INTO c; PERFORM public._festival_operations_create_commitment(op.festival_company_id,NULL,c.id,x.total_cost_minor,op.currency_code); UPDATE public.festival_supplier_quotes SET status=CASE WHEN id=x.id THEN 'accepted' ELSE 'superseded' END,quote_version=quote_version+1,updated_at=now() WHERE supplier_requirement_id=r.id AND status IN ('submitted','under_review'); UPDATE public.festival_supplier_requirements SET status='contracted',updated_at=now() WHERE id=r.id; INSERT INTO public.festival_supplier_allocations(supplier_contract_id,supplier_requirement_id,quantity,allocation_type) VALUES(c.id,r.id,least(r.quantity,coalesce(x.capacity_offered,r.quantity)),'contracted'); PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'supplier_contract',c.id,'contract_created',NULL,'committed',1); IF x.supplier_company_id IS NOT NULL THEN PERFORM public._festival_operations_notify(q.id,NULL,x.supplier_company_id,'contract_created','Festival supplier quote accepted','This creates a contractual commitment. Payment occurs during a later Festival settlement phase.','/companies'); END IF; RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(c)); END $$;

CREATE OR REPLACE FUNCTION public.cancel_festival_supplier_contract(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();c public.festival_supplier_contracts%ROWTYPE;op public.festival_operations_plans%ROWTYPE;q public.festival_operations_requests%ROWTYPE; BEGIN SELECT * INTO c FROM public.festival_supplier_contracts WHERE id=(p_payload->>'contractId')::uuid FOR UPDATE; SELECT * INTO op FROM public.festival_operations_plans WHERE id=c.festival_operations_plan_id; IF NOT public._festival_operations_authorised(op.festival_company_id,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'cancel_supplier_contract',c.id,p_idempotency_key,p_payload); IF q.status='succeeded' THEN RETURN q.result; END IF; IF c.contract_version<>(p_payload->>'expectedContractVersion')::int OR c.status NOT IN ('committed','awaiting_delivery') OR coalesce(c.delivery_start,c.service_start)<=now() THEN RAISE EXCEPTION 'festival_supplier_contract_invalid_transition' USING ERRCODE='P0001'; END IF; UPDATE public.festival_supplier_contracts SET status='cancelled',cancelled_at=now(),updated_at=now(),contract_version=contract_version+1 WHERE id=c.id RETURNING * INTO c; UPDATE public.festival_supplier_requirements SET status='published',updated_at=now() WHERE id=c.supplier_requirement_id; PERFORM public._festival_operations_cancel_commitment(NULL,c.id); PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'supplier_contract',c.id,'contract_cancelled','committed','cancelled',c.contract_version); RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,to_jsonb(c)); END $$;

CREATE OR REPLACE FUNCTION public.refresh_festival_npc_supplier_quotes(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();op public.festival_operations_plans%ROWTYPE;r public.festival_supplier_requirements%ROWTYPE;x public.festival_supplier_quotes%ROWTYPE;q public.festival_operations_requests%ROWTYPE;arr jsonb:='[]';seed bigint;price bigint; BEGIN SELECT * INTO op FROM public.festival_operations_plans WHERE festival_company_id=(p_payload->>'festivalCompanyId')::uuid FOR UPDATE; IF NOT public._festival_operations_authorised(op.festival_company_id,a) THEN RAISE EXCEPTION 'festival_operations_forbidden' USING ERRCODE='P0001'; END IF; q:=public._festival_operations_begin_action(op.festival_company_id,'refresh_npc_supplier_quotes',op.id,p_idempotency_key,p_payload||jsonb_build_object('refreshWindow',date_trunc('day',now()))); IF q.status='succeeded' THEN RETURN q.result; END IF; IF EXISTS(SELECT 1 FROM public.festival_operations_audit WHERE festival_company_id=op.festival_company_id AND event_type='npc_quotes_refreshed' AND created_at>now()-interval '24 hours') THEN RAISE EXCEPTION 'festival_supplier_refresh_cooldown' USING ERRCODE='P0001'; END IF; FOR r IN SELECT * FROM public.festival_supplier_requirements z WHERE z.festival_operations_plan_id=op.id AND z.status='published' AND z.npc_supplier_eligible AND NOT EXISTS(SELECT 1 FROM public.festival_supplier_contracts WHERE supplier_requirement_id=z.id AND status<>'cancelled') ORDER BY z.id LIMIT 5 LOOP seed:=abs(hashtextextended(r.id::text||date_trunc('day',now())::text,0)); price:=greatest(r.estimated_cost_minor,r.quantity*1000)*(90+(seed%41))/100; INSERT INTO public.festival_supplier_quotes(supplier_requirement_id,supplier_source,npc_supplier_id,currency_code,base_cost_minor,delivery_cost_minor,setup_cost_minor,staffing_cost_minor,deposit_minor,total_cost_minor,quality_score,reliability_score,capacity_offered,expires_at) VALUES(r.id,'npc_supplier',md5(r.id::text||date_trunc('day',now())::text)::uuid,op.currency_code,price,0,0,0,price/5,price,greatest(r.minimum_quality,40+(seed%45)),45+(seed%45),r.quantity,least(coalesce(r.delivery_start,now()+interval '8 days')-interval '1 day',now()+interval '7 days')) RETURNING * INTO x; arr:=arr||to_jsonb(x); END LOOP; PERFORM public._festival_operations_audit(q.id,op.festival_company_id,'operations_plan',op.id,'npc_quotes_refreshed',op.status,op.status,op.planning_version); RETURN public._festival_operations_finish_action(q.id,op.festival_company_id,jsonb_build_object('quotes',arr,'refreshWindow',date_trunc('day',now()),'cooldownHours',24)); END $$;

CREATE OR REPLACE FUNCTION public.get_available_festival_staff_vacancies(p_filters jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('id',v.id,'festivalCompanyId',op.festival_company_id,'title',v.title,'description',v.description,'role',r.role_type,'department',d.name,'employmentType',v.employment_type,'payMinor',v.pay_minor,'currencyCode',v.currency_code,'positionsRemaining',v.positions_available-v.positions_filled,'minimumSkillLevel',v.minimum_skill_level,'minimumExperience',v.minimum_experience,'startsAt',v.starts_at,'endsAt',v.ends_at,'deadline',v.application_deadline,'playerEligible',r.player_eligible,'scheduleCompatibility','unknown','travelSummary','unknown')),'[]'::jsonb)) FROM public.festival_staff_vacancies v JOIN public.festival_staffing_requirements r ON r.id=v.staffing_requirement_id JOIN public.festival_operational_departments d ON d.id=r.department_id JOIN public.festival_operations_plans op ON op.id=v.festival_operations_plan_id WHERE auth.uid() IS NOT NULL AND v.status='published' AND v.application_deadline>now() AND v.positions_filled<v.positions_available AND (p_filters->>'department' IS NULL OR d.department_type=p_filters->>'department') AND (p_filters->>'employmentType' IS NULL OR v.employment_type=p_filters->>'employmentType') AND (p_filters->>'minimumPayMinor' IS NULL OR v.pay_minor>=(p_filters->>'minimumPayMinor')::bigint) $$;
CREATE OR REPLACE FUNCTION public.get_available_festival_supplier_opportunities(p_filters jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('id',r.id,'festivalCompanyId',op.festival_company_id,'category',r.category,'description',r.description,'quantity',r.quantity,'unit',r.unit_type,'minimumQuality',r.minimum_quality,'deliveryStart',r.delivery_start,'deliveryEnd',r.delivery_end,'serviceStart',r.service_start,'serviceEnd',r.service_end,'playerCompanyEligible',r.player_company_eligible,'eligibility',jsonb_build_object('canQuote',r.player_company_eligible,'authority','server_verified','reasonCodes','[]'::jsonb))),'[]'::jsonb)) FROM public.festival_supplier_requirements r JOIN public.festival_operations_plans op ON op.id=r.festival_operations_plan_id WHERE auth.uid() IS NOT NULL AND r.status='published' AND (p_filters->>'category' IS NULL OR r.category=p_filters->>'category') $$;

-- Completion now requires workflow evidence, not marketplace interest.
CREATE OR REPLACE FUNCTION public._festival_operations_workflows_ready(p_plan uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.festival_staffing_requirements r WHERE r.festival_operations_plan_id=p_plan AND ((SELECT count(*) FROM public.festival_staff_assignments a WHERE a.staffing_requirement_id=r.id AND a.status IN ('committed','active') AND (NOT r.safety_critical OR a.quality_score>=r.minimum_skill_level))<r.required_count OR NOT EXISTS(SELECT 1 FROM public.festival_staff_shifts s JOIN public.festival_staff_assignments a ON a.id=s.staff_assignment_id WHERE a.staffing_requirement_id=r.id AND s.status='planned'))) AND NOT EXISTS(SELECT 1 FROM public.festival_supplier_requirements r WHERE r.festival_operations_plan_id=p_plan AND r.safety_critical AND NOT EXISTS(SELECT 1 FROM public.festival_supplier_contracts c JOIN public.festival_financial_commitments f ON f.supplier_contract_id=c.id AND f.status='committed' WHERE c.supplier_requirement_id=r.id AND c.status IN ('committed','awaiting_delivery','active'))) AND NOT EXISTS(SELECT 1 FROM public.festival_staff_assignments a LEFT JOIN public.festival_financial_commitments f ON f.staff_assignment_id=a.id AND f.status='committed' WHERE a.festival_operations_plan_id=p_plan AND a.status IN ('committed','active') AND f.id IS NULL) $$;

DROP FUNCTION IF EXISTS public._festival_operations_not_implemented();
REVOKE ALL ON FUNCTION public._festival_operations_authorised(uuid,uuid),public._festival_supplier_authorised(uuid,uuid),public._festival_operations_begin_action(uuid,text,uuid,uuid,jsonb),public._festival_operations_finish_action(uuid,uuid,jsonb),public._festival_operations_audit(uuid,uuid,text,uuid,text,text,text,integer),public._festival_operations_notify(uuid,uuid,uuid,text,text,text,text),public._festival_operations_create_commitment(uuid,uuid,uuid,bigint,text),public._festival_operations_cancel_commitment(uuid,uuid),public._festival_operations_workflows_ready(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_available_festival_staff_vacancies(jsonb),public.get_available_festival_supplier_opportunities(jsonb) TO authenticated;
NOTIFY pgrst,'reload schema';
